package com.example.data

import com.example.BuildConfig
import io.github.jan.supabase.auth.Auth
import io.github.jan.supabase.auth.FlowType
import io.github.jan.supabase.postgrest.Postgrest
import io.github.jan.supabase.createSupabaseClient

/**
 * Shared Supabase client for E50.
 *
 * The actual project URL and publishable key are read from BuildConfig,
 * generated by the Google Secrets Gradle Plugin from the root .env file.
 * Do not put a Supabase secret/service-role key in the Android app.
 */
object SupabaseClientProvider {

    private val projectUrl: String
        get() = BuildConfig.SUPABASE_URL.trim()

    private val publishableKey: String
        get() = BuildConfig.SUPABASE_PUBLISHABLE_KEY.trim()

    val isConfigured: Boolean
        get() = projectUrl.startsWith("https://") &&
            !projectUrl.contains("YOUR_PROJECT_REF") &&
            publishableKey.isNotBlank() &&
            !publishableKey.contains("YOUR_SUPABASE_PUBLISHABLE_KEY")

    val client by lazy(LazyThreadSafetyMode.SYNCHRONIZED) {
        check(isConfigured) {
            "Supabase is not configured. Add SUPABASE_URL and SUPABASE_PUBLISHABLE_KEY to the root .env file."
        }

        createSupabaseClient(
            supabaseUrl = projectUrl,
            supabaseKey = publishableKey
        ) {
            install(Postgrest)
            install(Auth) {
                flowType = FlowType.PKCE
                scheme = "com.aistudio.e50.ecoact.final"
                host = "auth-callback"
            }
        }
    }
}
